/**
 * Generates packages/core/src/agents/prompts.generated.ts from the .txt prompt files.
 * The prompt files are copied verbatim from OpenCode (MIT licensed).
 *
 * Usage: bun run scripts/build-prompts.ts
 */
import { readdirSync, readFileSync, writeFileSync } from "node:fs"
import path from "node:path"

const dir = path.join(import.meta.dir, "../packages/core/src/agents/prompts")
const out = path.join(import.meta.dir, "../packages/core/src/agents/prompts.generated.ts")

const files = readdirSync(dir).filter((f) => f.endsWith(".txt"))

const parts: string[] = [
  "// AUTO-GENERATED by scripts/build-prompts.ts. Do not edit.",
  "// Prompt texts copied verbatim from OpenCode (MIT licensed, https://github.com/anomalyco/opencode).",
  "",
]

for (const file of files) {
  const name = file.replace(/\.txt$/, "").replaceAll(/[.-]/g, "_")
  const content = readFileSync(path.join(dir, file), "utf8")
  parts.push(`export const ${name} = ${JSON.stringify(content)}`)
  parts.push("")
}

writeFileSync(out, parts.join("\n"))
console.log(`Wrote ${out} (${files.length} prompts: ${files.join(", ")})`)
